#include <bits/stdc++.h>
using namespace std;
// Same work, same Big-O O(N*N): only the memory access order differs.
int main() {
    const int N = 2048;
    vector<int> m(N * N, 1);              // row-major: m[r*N + c]
    auto t0 = chrono::steady_clock::now();
    long long rowSum = 0;
    for (int r = 0; r < N; r++)           // walks memory sequentially (cache friendly)
        for (int c = 0; c < N; c++) rowSum += m[r * N + c];
    auto t1 = chrono::steady_clock::now();
    long long colSum = 0;
    for (int c = 0; c < N; c++)           // jumps N*4 bytes each step (cache hostile)
        for (int r = 0; r < N; r++) colSum += m[r * N + c];
    auto t2 = chrono::steady_clock::now();
    cout << "matrix " << N << "x" << N << " of ones\n";
    cout << "row-order sum = " << rowSum << "\n";
    cout << "column-order sum = " << colSum << "\n";
    // Times go to stderr because they differ per machine; column order is usually slower.
    cerr << "row ms " << chrono::duration<double, milli>(t1 - t0).count()
         << ", column ms " << chrono::duration<double, milli>(t2 - t1).count() << "\n";
}

#include <bits/stdc++.h>
using namespace std;
struct Bad  { char a; double b; char c; };      // 1 + 7 pad + 8 + 1 + 7 tail = 24
struct Good { double b; char a; char c; };      // 8 + 1 + 1 + 6 tail = 16
struct Flags { unsigned ready : 1; unsigned dirty : 1; unsigned kind : 6; };
// static_assert locks the layout in at compile time
static_assert(sizeof(Good) == 16, "layout changed");
int main() {
    cout << "alignof(double) = " << alignof(double) << "\n";
    cout << "sizeof(Bad)   = " << sizeof(Bad) << "\n";
    cout << "sizeof(Good)  = " << sizeof(Good) << "\n";
    cout << "sizeof(Flags) = " << sizeof(Flags) << "\n";
    // offsetof shows where padding was inserted
    cout << "Bad offsets: a=" << offsetof(Bad, a) << " b=" << offsetof(Bad, b)
         << " c=" << offsetof(Bad, c) << "\n";
    cout << "Good offsets: b=" << offsetof(Good, b) << " a=" << offsetof(Good, a)
         << " c=" << offsetof(Good, c) << "\n";
    cout << "1000 Bad = " << 1000 * sizeof(Bad) << " bytes, 1000 Good = "
         << 1000 * sizeof(Good) << " bytes\n";
}

#include <bits/stdc++.h>
using namespace std;
// Two counters written by two threads. Packed: they share one 64-byte cache line.
struct Packed { long a = 0; long b = 0; };
struct Padded { alignas(64) long a = 0; alignas(64) long b = 0; }; // one line each
template <class T>
double run(T& t, long n) {
    auto t0 = chrono::steady_clock::now();
    thread x([&] { volatile long* p = &t.a; for (long i = 0; i < n; i++) *p = *p + 1; });
    thread y([&] { volatile long* p = &t.b; for (long i = 0; i < n; i++) *p = *p + 1; });
    x.join(); y.join();
    return chrono::duration<double, milli>(chrono::steady_clock::now() - t0).count();
}
int main() {
    const long n = 20000000;
    Packed pk; Padded pd;
    double tp = run(pk, n), tq = run(pd, n);
    cout << "packed: a=" << pk.a << " b=" << pk.b << " sizeof=" << sizeof(Packed) << "\n";
    cout << "padded: a=" << pd.a << " b=" << pd.b << " sizeof=" << sizeof(Padded) << "\n";
    // Results are identical; only the time differs (packed is usually much slower).
    cerr << "packed ms " << tp << ", padded ms " << tq << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// Branchy and branchless versions of the same sum.
long long branchy(const vector<int>& v) {
    long long s = 0;
    for (int x : v) if (x >= 128) s += x;      // data-dependent branch
    return s;
}
long long branchless(const vector<int>& v) {
    long long s = 0;
    for (int x : v) s += (x >= 128) * x;       // no branch: condition becomes 0 or 1
    return s;
}
int main() {
    mt19937 rng(42);
    vector<int> v(1 << 20);
    for (int& x : v) x = rng() % 256;
    vector<int> sorted = v;
    sort(sorted.begin(), sorted.end());        // sorted: branch is predictable
    cout << "unsorted branchy    = " << branchy(v) << "\n";
    cout << "sorted branchy      = " << branchy(sorted) << "\n";
    cout << "unsorted branchless = " << branchless(v) << "\n";
    // Same answers; timing (not printed) differs when the compiler keeps the branch.
    auto t0 = chrono::steady_clock::now();
    long long a = branchy(v);
    auto t1 = chrono::steady_clock::now();
    long long b = branchy(sorted);
    auto t2 = chrono::steady_clock::now();
    cerr << (a == b) << " unsorted ms " << chrono::duration<double, milli>(t1 - t0).count()
         << " sorted ms " << chrono::duration<double, milli>(t2 - t1).count() << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// inline is about linkage: this could live in a header included by many .cpp files.
constexpr inline int square(int x) { return x * x; }
inline int counterValue = 10;                 // C++17 inline variable: one object program-wide
[[gnu::noinline]] int notInlined(int x) { return x + 1; }   // forbid inlining on purpose
constexpr int sq5 = square(5);                // usable at compile time too
int main() {
    // The compiler may inline square(); the call below behaves the same either way.
    int total = 0;
    for (int i = 1; i <= 5; i++) total += square(i);   // 1+4+9+16+25
    cout << "sum of squares 1..5 = " << total << "\n";
    cout << "compile-time square(5) = " << sq5 << "\n";
    cout << "inline variable = " << counterValue << "\n";
    cout << "noinline call = " << notInlined(41) << "\n";
    // Address of an inline function is the same everywhere in the program.
    int (*f)(int) = square;
    cout << "via pointer square(7) = " << f(7) << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// As-if rule: -O2 may replace this whole loop by n*(n-1)/2 because output is the same.
long long sumTo(int n) {
    long long s = 0;
    for (int i = 0; i < n; i++) s += i;     // induction-variable simplification
    return s;
}
// Dead store elimination: 'tmp' is never observed, so it may vanish entirely.
int deadStore(int x) {
    int tmp = x * 100;
    tmp = 7;
    return x + 1;
}
// Constant folding: the compiler computes this at compile time.
constexpr int folded() { return 6 * 7 + 1; }
int main() {
    int n = 1000;
    cout << "loop result   = " << sumTo(n) << "\n";
    cout << "formula       = " << (long long)n * (n - 1) / 2 << "\n";
    cout << "deadStore(4)  = " << deadStore(4) << "\n";
    cout << "folded()      = " << folded() << "\n";
    // Observable behaviour (this output) is identical at -O0 and -O2.
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    // Implementation-defined: documented by the compiler, differs by platform.
    cout << "sizeof(long) = " << sizeof(long) << ", char is "
         << (numeric_limits<char>::is_signed ? "signed" : "unsigned") << "\n";
    // Defined: unsigned overflow wraps modulo 2^32.
    unsigned u = numeric_limits<unsigned>::max();
    cout << "UINT_MAX + 1 = " << u + 1 << "\n";
    // Unspecified (not shown): in f(g(), h()) either call may run first; the program stays valid.
    // Undefined (NOT executed): INT_MAX + 1 has no requirements at all.
    // Safe way to detect it before it happens:
    int big = numeric_limits<int>::max();
    bool wouldOverflow = big > numeric_limits<int>::max() - 1;
    cout << "INT_MAX + 1 would overflow: " << boolalpha << wouldOverflow << "\n";
    long long wide = (long long)big + 1;     // widen first: well defined
    cout << "widened INT_MAX + 1 = " << wide << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    // (1) Midpoint overflow: lo + hi exceeds INT_MAX (we compute it in 64 bits to stay safe).
    int lo = 2000000000, hi = 2100000000;
    long long wrong = (long long)lo + hi;          // what int would need to hold
    cout << "lo+hi needs " << wrong << " (INT_MAX " << INT_MAX << ")\n";
    cout << "safe mid     = " << lo + (hi - lo) / 2 << "\n";
    cout << "std::midpoint = " << midpoint(lo, hi) << "\n";
    // (2) push_back inside a loop over iterators can invalidate them: iterate by index.
    vector<int> v = {1, 0, 2, 0};
    size_t n = v.size();                           // fix the original size
    for (size_t i = 0; i < n; i++)
        if (v[i] == 0) v.push_back(1);             // indexes stay valid after reallocation
    cout << "v =";
    for (int x : v) cout << " " << x;
    cout << "\n";
    // (3) String literals are read-only: copy into an array to modify.
    char p[] = "abc";                              // modifiable copy
    p[0] = 'X';
    cout << "modified copy = " << p << "\n";
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    float f = 1.0f;
    // WRONG (UB): *(uint32_t*)&f  breaks strict aliasing. Do one of these instead:
    uint32_t viaCast = bit_cast<uint32_t>(f);      // C++20, constexpr
    uint32_t viaCopy;
    memcpy(&viaCopy, &f, sizeof f);                // compiles to a register move
    cout << hex << showbase;
    cout << "bit_cast bits of 1.0f = " << viaCast << "\n";
    cout << "memcpy   bits of 1.0f = " << viaCopy << "\n";
    // Extract the sign / exponent / mantissa fields from the bits.
    cout << dec;
    cout << "sign=" << (viaCast >> 31) << " exponent=" << ((viaCast >> 23) & 0xFF)
         << " mantissa=" << (viaCast & 0x7FFFFF) << "\n";
    // Reading any object as bytes is always allowed (char/unsigned char/std::byte).
    unsigned char* bytes = reinterpret_cast<unsigned char*>(&f);
    cout << "first byte of 1.0f (little-endian) = " << (int)bytes[0] << "\n";
    // Round trip back to float.
    cout << "back to float = " << bit_cast<float>(viaCast) << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// Toy model of ASan: 1 shadow byte per 8-byte granule. 0 = all 8 ok, 1..7 = partial, -1 = poisoned.
struct Shadow {
    vector<signed char> s;
    Shadow(size_t bytes) : s(bytes / 8, -1) {}   // everything starts poisoned
    void allocate(size_t addr, size_t n) {       // unpoison n bytes starting at addr (8-aligned)
        for (size_t i = 0; i < n / 8; i++) s[addr / 8 + i] = 0;
        if (n % 8) s[addr / 8 + n / 8] = n % 8;  // partial granule
    }
    bool ok(size_t addr, size_t size) {          // the check inserted before each access
        signed char k = s[addr >> 3];            // shift + load + compare
        if (k == 0) return true;
        if (k < 0) return false;
        return (addr & 7) + size <= (size_t)k;
    }
};
int main() {
    Shadow sh(256);
    sh.allocate(64, 10);                         // a 10-byte object at address 64
    for (size_t off : {0, 9, 10, 16}) {
        cout << "access at +" << off << ": " << (sh.ok(64 + off, 1) ? "ok" : "ERROR redzone") << "\n";
    }
    cout << "shadow bytes: " << (int)sh.s[8] << " " << (int)sh.s[9] << " " << (int)sh.s[10] << "\n";
    // Accessing +16 lands in a poisoned redzone; a jump far past it could land in a valid object.
}

#include <bits/stdc++.h>
using namespace std;
// Minimal DoNotOptimize: an empty asm that "uses" the value so the optimiser must compute it.
template <class T> void doNotOptimize(const T& v) { asm volatile("" : : "g"(v) : "memory"); }
int work(int n) { int s = 0; for (int i = 0; i < n; i++) s += i % 7; return s; }
int main() {
    const int reps = 5, n = 1000000;
    vector<double> ms;
    for (int r = 0; r < reps; r++) {                // repetitions give a distribution, not one number
        auto t0 = chrono::steady_clock::now();
        int result = work(n);
        doNotOptimize(result);                      // without this the loop could be deleted
        ms.push_back(chrono::duration<double, milli>(chrono::steady_clock::now() - t0).count());
        if (r == 0) cout << "work(" << n << ") = " << result << "\n";
    }
    sort(ms.begin(), ms.end());
    cout << "repetitions: " << ms.size() << "\n";
    cout << "report median of runs, not the minimum only\n";
    cerr << "median ms " << ms[ms.size() / 2] << " min " << ms.front() << " max " << ms.back() << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// Amdahl: speedup = 1 / ((1 - p) + p / s)
double amdahl(double p, double s) { return 1.0 / ((1 - p) + p / s); }
int main() {
    cout << fixed << setprecision(3);
    // 60% of runtime made 3x faster
    cout << "p=0.60, s=3      -> " << amdahl(0.60, 3) << "x\n";
    // limit when s is huge: 1 / (1 - p)
    cout << "p=0.20, s=1e9    -> " << amdahl(0.20, 1e9) << "x (cap 1.25)\n";
    // parallel: 5% serial part caps speedup at 20x
    for (int cores : {2, 8, 64, 1024})
        cout << "p=0.95, cores=" << cores << " -> " << amdahl(0.95, cores) << "x\n";
    // Pick the best target: gain per candidate hot spot
    vector<pair<string, pair<double, double>>> spots = {{"parse", {0.50, 2}}, {"log", {0.10, 10}}};
    for (auto& [name, ps] : spots)
        cout << name << ": overall " << amdahl(ps.first, ps.second) << "x\n";
}

#include <bits/stdc++.h>
using namespace std;
int main() {
    // Saturating arithmetic (C++26 std::add_sat; same behaviour written by hand here).
    auto addSat = [](int a, int b) {
        long long r = (long long)a + b;
        return (int)clamp<long long>(r, INT_MIN, INT_MAX);
    };
    cout << "INT_MAX + 5 saturated = " << addSat(INT_MAX, 5) << "\n";
    cout << "100 + 5 saturated     = " << addSat(100, 5) << "\n";
    // Hardened indexing: a checked access traps/throws instead of undefined behaviour.
    vector<int> v = {10, 20, 30};
    try {
        cout << "v.at(1) = " << v.at(1) << "\n";
        cout << "v.at(7) = " << v.at(7) << "\n";     // v[7] would be UB; at() is defined
    } catch (const out_of_range&) {
        cout << "caught out_of_range for index 7\n";
    }
    // Zero-initialised locals: what -ftrivial-auto-var-init=zero or erroneous behaviour gives you.
    int x{};
    cout << "value-initialised x = " << x << "\n";
}
